<?php
declare(strict_types=1);
namespace Shipping;
final class Ledger
{
    public function __construct(public readonly Database $db,private readonly Settings $settings){}
    public static function audit(Unit $u,string $run,?array $a,string $outcome,int $status,?string $target=null):void {if($a===null)return;$u->execute('INSERT INTO command_audit(id,run_id,actor,role,request_id,action,outcome,status_code,idempotency_key,peer,target_id) VALUES (?,?,?,?,?,?,?,?,?,?,?)',[Rules::uuid4(),$run,$a['actor'],$a['role'],$a['request_id'],substr($a['action'],0,256),$outcome,$status,substr($a['idempotency_key']??'',0,128),substr($a['peer']??'',0,128),$target]);}
    public function scope():string {return $this->db->transaction(fn($u)=>$u->run()['id']);}
    public function status():array {return $this->db->transaction(fn($u)=>self::statusWithin($u));}
    private static function statusWithin(Unit $u):array {$r=$u->run();return ['run'=>$r,'jobs'=>$u->query('SELECT * FROM jobs WHERE run_id=? ORDER BY created_at DESC LIMIT 100',[$r['id']]),'effects'=>(int)$u->one('SELECT COALESCE(sum(quantity),0) AS n FROM effects WHERE run_id=?',[$r['id']])['n'],'heartbeats'=>$u->query("SELECT role,seen_at,detail,seen_at>clock_timestamp()-interval '15 seconds' AS healthy FROM heartbeats"),'pending_boundary_outputs'=>(int)$u->one('SELECT count(*) AS n FROM boundary_outbox WHERE run_id=? AND sent_at IS NULL',[$r['id']])['n']];}

    public function auditEvents():array {return $this->db->transaction(fn($u)=>$u->query('SELECT * FROM command_audit ORDER BY recorded_at DESC,id DESC LIMIT 100'));}
    public function rejected(array $a,int $status):void {$this->db->transaction(function($u)use($a,$status){self::audit($u,$a['run_id']??$u->run()['id'],$a,'rejected',$status);});}
    public function relayFleet():void {Fleet::relay($this->db);}
    public function heartbeat(string $role,string $detail=''):void {$this->db->transaction(fn($u)=>$u->execute('INSERT INTO heartbeats(role,detail) VALUES (?,?) ON CONFLICT(role) DO UPDATE SET seen_at=clock_timestamp(),detail=EXCLUDED.detail',[$role,$detail]));}
    public function schedule(string $key,float $due,int $quantity,?array $audit=null,?array $input=null):array {
        if(!$key||strlen($key)>128||!is_finite($due)||$due<0||$quantity<1||$quantity>10000)throw new Validation('Valid idempotency key, finite due time and quantity required');
        return $this->db->transaction(function($u)use($key,$due,$quantity,$audit,$input){$r=$u->run();$payload=['quantity'=>$quantity];if($input&&($input['run_id']!==$r['id']||$input['epoch']!==$r['epoch']))throw new Conflict('Seeded input belongs to a different run or epoch');
            $old=$u->query('SELECT * FROM jobs WHERE run_id=? AND idempotency_key=?',[$r['id'],$key])[0]??null;if($old){if($old['original_due_at']!=$due||$old['payload']!=$payload||$old['boundary_input']!=$input)throw new Conflict('Idempotency key already used with a different command');self::audit($u,$r['id'],$audit,'accepted',200,$old['id']);return $old;}
            if(!in_array($r['state'],['running','held'],true)||$due<max($r['granted'],$r['requested'])+$this->settings->quantum)throw new Conflict('Schedule at least one quantum beyond granted/requested time in an active run');
            $job=$u->one('INSERT INTO jobs(id,run_id,epoch,idempotency_key,due_at,original_due_at,payload,boundary_input) VALUES (?,?,?,?,?,?,?,?) RETURNING *',[Rules::uuid4(),$r['id'],$r['epoch'],$key,$due,$due,$payload,$input]);self::audit($u,$r['id'],$audit,'accepted',200,$job['id']);return $job;
        });
    }
    public static function outstanding(Unit $u,array $r):bool {return $u->one("SELECT EXISTS(SELECT 1 FROM jobs WHERE run_id=? AND due_at<=? AND status NOT IN ('completed','fenced')) OR EXISTS(SELECT 1 FROM boundary_outbox WHERE run_id=? AND sent_at IS NULL) AS busy",[$r['id'],$r['granted'],$r['id']])['busy'];}
    public function control(string $action,array $body,array $audit):array {
        Rules::fields($body,['speed','confirm_run_id','scenario','run_id','epoch']);$speed=array_key_exists('speed',$body)?Rules::integer($body['speed'],PHP_INT_MIN,PHP_INT_MAX):1;$confirm=isset($body['confirm_run_id'])?Rules::uuid($body['confirm_run_id']):null;$scenario=isset($body['scenario'])?new Scenario($body['scenario']):null;
        if($scenario&&$action!=='reset')throw new Conflict('Scenario changes require a confirmed new run');
        return $this->db->transaction(function($u)use($action,$speed,$confirm,$scenario,$audit,$body){$r=$u->run();if(isset($body['run_id'])&&Rules::uuid($body['run_id'])!==$r['id']||isset($body['epoch'])&&Rules::uuid($body['epoch'])!==$r['epoch'])throw new Conflict('Control belongs to a different run or epoch');
            $key=in_array($action,['hold','resume'],true)&&str_starts_with($audit['action']??'','POST /api/control/')&&is_string($audit['idempotency_key']??null)&&$audit['idempotency_key']!==''?$audit['idempotency_key']:null;
            if($key!==null){if(strlen($key)>128)throw new Validation('Idempotency-Key length must be 1..128');$old=$u->query('SELECT action,request,response FROM control_receipts WHERE run_id=? AND actor=? AND idempotency_key=?',[$r['id'],$audit['actor'],$key])[0]??null;if($old){if($old['action']!==$action||$old['request']!=$body)throw new Conflict('Idempotency key already used with a different control');self::audit($u,$r['id'],$audit,'accepted',200);return $old['response'];}}
            switch($action){
            case 'reset':if($confirm!==$r['id'])throw new Conflict('Reset requires the current run ID as confirmation');if($r['mode']==='helics')throw new Conflict('Finalize federation and allocate a new deployment run/epoch; live reset forbidden');$u->execute('UPDATE runs SET current=false WHERE id=?',[$r['id']]);$u->execute('INSERT INTO runs(id,epoch,mode,scenario) VALUES (?,?,?,?)',[Rules::uuid4(),Rules::uuid4(),$this->settings->mode,$scenario?->body??$r['scenario']]);break;
            case 'hold':case 'resume':if(!in_array($r['state'],['running','held'],true))throw new Conflict('Cannot resume a failed, stalled or finalized run');$u->execute('UPDATE runs SET state=?,anchor=clock_timestamp() WHERE id=?',[$action==='hold'?'held':'running',$r['id']]);break;
            case 'speed':if($r['mode']!=='standalone'||!in_array($speed,[1,5,20,60],true))throw new Conflict('Only standalone speeds 1,5,20,60 supported');$u->execute('UPDATE runs SET speed=?,anchor=clock_timestamp() WHERE id=?',[$speed,$r['id']]);break;
            case 'finalize':if(self::outstanding($u,$r))throw new Conflict('Hold and settle current-time work before finalizing');if($r['mode']==='helics'&&!$u->query("SELECT 1 FROM shipping_adapter_sessions WHERE run_id=? AND epoch=? AND NOT native_pending AND native_state='executing'",[$r['id'],$r['epoch']]))throw new Conflict('Native initialization, request or receive is unsettled; hold and wait before finalizing');if($r['mode']==='helics'){$u->execute("UPDATE shipping_adapter_sessions SET native_pending=true,native_state='finalizing' WHERE run_id=?",[$r['id']]);$u->execute("UPDATE runs SET state='finalizing' WHERE id=?",[$r['id']]);}else $u->execute("UPDATE runs SET state='finalized' WHERE id=?",[$r['id']]);break;
            default:throw new Conflict('Unknown control');
        }self::audit($u,$r['id'],$audit,'accepted',200);$response=self::statusWithin($u);if($key!==null)$u->execute('INSERT INTO control_receipts(run_id,actor,idempotency_key,action,request,response) VALUES (?,?,?,?,?,?)',[$r['id'],$audit['actor'],$key,$action,$body,$response]);return $response;});
    }
    public function execute(string $jobId):string {return $this->db->transaction(function($u)use($jobId){$r=$u->run();$j=$u->query('SELECT * FROM jobs WHERE id=? FOR UPDATE',[$jobId])[0]??null;if(!$j||$j['run_id']!==$r['id']||$j['epoch']!==$r['epoch'])return 'fenced';if($j['status']==='completed')return 'duplicate';if($j['status']==='dead')return 'dead';
        if($r['state']!=='running'||$j['due_at']>$r['granted']||!$u->query("SELECT 1 FROM heartbeats WHERE role='controller' AND seen_at>clock_timestamp()-interval '15 seconds'")||!$u->one('SELECT retry_after<=clock_timestamp() AS ready FROM jobs WHERE id=?',[$jobId])['ready'])return 'waiting';
        if(isset($j['payload']['shipping'])){$u->execute('INSERT INTO inbox(event_id,run_id,epoch) VALUES (?,?,?) ON CONFLICT DO NOTHING',[$jobId,$r['id'],$r['epoch']]);if(!(new Fulfilment($this->db,$this->settings))->execute($u,$r,$j))return 'waiting';$u->execute("UPDATE jobs SET status='completed',error=NULL WHERE id=?",[$jobId]);return 'completed';}
        $u->execute('INSERT INTO inbox(event_id,run_id,epoch) VALUES (?,?,?) ON CONFLICT DO NOTHING',[$jobId,$r['id'],$r['epoch']]);$quantity=Rules::integer($j['payload']['quantity']??null,1,10000);$u->execute('INSERT INTO effects(job_id,run_id,quantity) VALUES (?,?,?)',[$jobId,$r['id'],$quantity]);$u->execute("UPDATE jobs SET status='completed',error=NULL WHERE id=?",[$jobId]);
        if($r['mode']==='helics'&&!str_starts_with($j['idempotency_key'],'boundary:'))$u->execute('INSERT INTO boundary_outbox(id,run_id,envelope) VALUES (?,?,?)',[Rules::uuid4(),$r['id'],['job_id'=>$jobId,'quantity'=>$quantity,'time'=>$r['granted']]]);return 'completed';
    });}
    public function fail(string $jobId,string $error):string {return $this->db->transaction(function($u)use($jobId,$error){$r=$u->run();$j=$u->query('SELECT * FROM jobs WHERE id=? FOR UPDATE',[$jobId])[0]??null;if(!$j||$j['run_id']!==$r['id']||in_array($j['status'],['completed','dead'],true))return $j&&$j['status']==='dead'?'dead':'fenced';$attempt=$j['attempts']+1;$state=$attempt>=3?'dead':'pending';$u->execute("UPDATE jobs SET attempts=?,status=?,error=?,retry_after=clock_timestamp()+interval '2 seconds' WHERE id=?",[$attempt,$state,substr($error,0,1000),$jobId]);if($attempt>=3)$u->execute("UPDATE runs SET state='failed',error='Job retry limit exceeded' WHERE id=?",[$r['id']]);return $attempt>=3?'dead':'retry';});}
    public function dispatchable():array {return $this->db->transaction(function($u){$r=$u->run();if($r['state']!=='running')return [];foreach($u->query("SELECT id FROM jobs WHERE run_id=? AND due_at<=? AND status IN ('pending','queued') AND retry_after<=clock_timestamp()",[$r['id'],$r['granted']]) as $j)$u->execute('INSERT INTO outbox(id,job_id,run_id) VALUES (?,?,?) ON CONFLICT(job_id) DO NOTHING',[Rules::uuid4(),$j['id'],$r['id']]);return $u->query("SELECT o.id,o.job_id FROM outbox o JOIN jobs j ON j.id=o.job_id WHERE o.run_id=? AND j.status IN ('pending','queued') AND j.retry_after<=clock_timestamp() AND o.retry_after<=clock_timestamp()",[$r['id']]);});}
    public function published(string $id):void {$this->db->transaction(function($u)use($id){$u->run();$u->execute("UPDATE outbox SET sent_at=clock_timestamp(),retry_after=clock_timestamp()+interval '5 seconds' WHERE id=?",[$id]);});}
    public function prepare(float $target,string $epoch):bool {return $this->db->transaction(function($u)use($target,$epoch){$r=$u->run();if($r['epoch']!==$epoch||$r['state']!=='running'||self::outstanding($u,$r))return false;if(!is_finite($target)||$target<=$r['granted'])throw new Conflict('Next request must advance time');
        if($r['mode']==='helics'){if(!$u->query("SELECT 1 FROM shipping_adapter_sessions WHERE run_id=? AND epoch=? AND NOT native_pending AND native_state='executing'",[$r['id'],$r['epoch']]))return false;$u->execute('UPDATE shipping_adapter_sessions SET native_pending=true WHERE run_id=?',[$r['id']]);}
        $u->execute('UPDATE runs SET committed=granted,requested=? WHERE id=?',[$target,$r['id']]);return true;
    });}
    public function grant(float $grant,string $epoch):bool {return $this->db->transaction(function($u)use($grant,$epoch){$r=$u->run();if($r['epoch']!==$epoch)throw new Conflict('Stale controller epoch');if(in_array($r['state'],['failed','stalled','finalized'],true)||$r['mode']==='standalone'&&$r['state']==='held')return false;if(!is_finite($grant)||$grant<$r['granted']||$grant>$r['requested'])throw new Conflict('Grant must be finite, monotonic and no later than requested');$u->execute('UPDATE runs SET granted=?,anchor=clock_timestamp() WHERE id=?',[$grant,$r['id']]);return true;});}
    public function stall(string $error,?string $epoch):void {$this->db->transaction(function($u)use($error,$epoch){if(!$u->one('SELECT pg_try_advisory_xact_lock(8192102) AS held')['held'])return;$r=$u->run();if($epoch!==null&&$epoch!==$r['epoch']||in_array($r['state'],['failed','stalled','finalized'],true))return;$u->execute("UPDATE runs SET state='stalled',error=? WHERE current",[substr($error,0,1000)]);});}
    public function seed():void {$r=$this->status()['run'];if($r['state']!=='running')return;$s=new Scenario($r['scenario']);$threshold=max($r['granted'],$r['requested'])+$this->settings->quantum;$slot=max(1,(int)ceil($threshold/$s->interval));$due=$s->nextDue(($slot-1)*$s->interval,(float)$s->interval);$slot=(int)ceil($due/$s->interval);
        foreach(['orders'=>'demand','goods'=>'receiving','carrier'=>'carrier'] as $boundary=>$kind){if($this->settings->providers[$boundary]!=='synthetic')continue;$inputId=Rules::uuid5($r['id'],$r['epoch'].":$boundary:$slot:".$s->seed);$key='synthetic:'.$inputId;if($this->db->transaction(fn($u)=>$u->query('SELECT 1 FROM jobs WHERE run_id=? AND idempotency_key=?',[$r['id'],$key])))continue;$quantity=Rules::quantity($s->seed,'shipping',$boundary,$slot);
            $input=['schema_version'=>'1.0','input_id'=>$inputId,'run_id'=>$r['id'],'epoch'=>$r['epoch'],'application'=>'shipping','boundary'=>$boundary,'kind'=>$kind,'provider'=>'synthetic','effective_time'=>$due,'quantity'=>$quantity,'quantity_unit'=>'item'];$audit=['actor'=>'shipping-synthetic','role'=>'service','request_id'=>$inputId,'action'=>'seed:'.$kind,'idempotency_key'=>$inputId,'peer'=>'controller'];$this->schedule($key,$due,$quantity,$audit,$input);
        }
    }
    public function ingest(array $raw,string $source):string {if(($raw['type']??'sample.completed.v1')!=='sample.completed.v1')return (new Fulfilment($this->db,$this->settings))->ingest($raw,$source);$e=Rules::envelope($raw);$peer=$this->settings->peers[$e['boundary']]??null;if(!$peer||($peer['endpoint']??null)!==$source||($peer['source']??null)!==$e['source']||$e['destination']!=='shipping'||$e['federation_id']!==$this->settings->federationId||($this->settings->providers[$e['boundary']]??null)!=='helics')throw new Conflict('Boundary owner/routing mismatch');
        return $this->db->transaction(function($u)use($e){$r=$u->run();if($e['run_id']!==$r['id']||$e['epoch']!==$r['epoch'])return 'fenced';if($u->query('SELECT 1 FROM inbox WHERE event_id=?',[$e['event_id']]))return 'duplicate';if($e['effective_time']<$r['granted'])throw new Conflict('Late event cannot change committed history');$u->execute('INSERT INTO inbox(event_id,run_id,epoch) VALUES (?,?,?)',[$e['event_id'],$r['id'],$r['epoch']]);$u->execute('INSERT INTO jobs(id,run_id,epoch,idempotency_key,due_at,original_due_at,payload) VALUES (?,?,?,?,?,?,?)',[Rules::uuid4(),$r['id'],$r['epoch'],'boundary:'.$e['event_id'],$e['effective_time'],$e['effective_time'],$e['payload']]);return 'accepted';});
    }
}
